(()=>{
 const $=s=>document.querySelector(s),money=p=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format((p||0)/100),date=v=>new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));
 let account,eventId=null,version,referralLink='';
 const extraStyles=document.createElement('link');extraStyles.rel='stylesheet';extraStyles.href='/admin-extra.css';document.head.append(extraStyles);
 const imageTools=document.createElement('div');imageTools.className='image-tools';imageTools.innerHTML='<label>Or upload an image<input id="image-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="image-preview" id="image-preview" hidden><img alt="Event image preview"><span>Banner preview</span></div><small>JPEG, PNG or WebP · maximum 8 MB.</small>';$('#editor').elements.image_url.closest('label').after(imageTools);
 const deleteButton=document.createElement('button');deleteButton.type='button';deleteButton.id='delete-event';deleteButton.className='danger';deleteButton.textContent='Delete event';$('#editor').querySelector('.form-actions').append(deleteButton);
 const deleteDialog=document.createElement('dialog');deleteDialog.className='delete-dialog';deleteDialog.innerHTML='<span class="eyebrow">PERMANENT ACTION</span><h2>Delete this event?</h2><p id="delete-copy"></p><p>Its passes and team assignments will also be removed. Events with registrations cannot be deleted and must be archived.</p><div><button type="button" class="quiet" data-cancel>Keep event</button><button type="button" class="danger" data-confirm>Delete permanently</button></div>';document.body.append(deleteDialog);
 const couponPanel=document.createElement('section');couponPanel.className='panel coupon-panel';couponPanel.hidden=true;couponPanel.innerHTML='<div class="panel-heading"><div><span class="eyebrow">PROMOTIONS</span><h3>Coupons</h3></div></div><form id="coupon-form"><div class="coupon-fields"><label>Code<input name="code" required pattern="[A-Z0-9_-]{3,32}" placeholder="EARLY20"></label><label>Scope<select name="event_id"><option value="">All events</option></select></label><label>Discount<select name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed amount</option></select></label><label>Value<input name="value" type="number" min="1" step="1" required></label><label>Minimum spend (₹)<input name="min_spend" type="number" min="0" step="1" value="0"></label><label>Maximum uses<input name="max_uses" type="number" min="1" step="1" placeholder="Unlimited"></label><label>Uses per customer<input name="per_customer" type="number" min="1" max="100" value="1"></label><label>Expires at<input name="expires_at" type="datetime-local"></label></div><button class="primary">Create coupon</button></form><div id="coupon-list" class="stack"></div>';$('#view-superadmin .admin-heading').after(couponPanel);
 function showImage(url){const preview=$('#image-preview');preview.hidden=!url;if(url)preview.querySelector('img').src=url;}
 const message=text=>{$('#message').textContent=text;if(text)setTimeout(()=>{if($('#message').textContent===text)$('#message').textContent='';},6000);};
 async function api(url,options={}){const headers={...options.headers};if(options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});const data=response.status===204?{}:await response.json();if(!response.ok)throw Error(data.details?.map(d=>`${d.field}: ${d.message}`).join('\n')||data.error||'Request failed');return data;}
 function empty(node,text){node.replaceChildren();const p=document.createElement('p');p.className='empty';p.textContent=text;node.append(p);}
 function switchView(name){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));document.querySelectorAll('.workspace-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));}
 document.querySelectorAll('.workspace-tabs button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
 function authMode(mode){$('#login').hidden=mode!=='login';$('#signup').hidden=mode!=='signup';$('#show-login').classList.toggle('active',mode==='login');$('#show-signup').classList.toggle('active',mode==='signup');message('');}
 $('#show-login').onclick=()=>authMode('login');$('#show-signup').onclick=()=>authMode('signup');
 function rows(node,items,renderer,none){if(!items.length)return empty(node,none);node.replaceChildren();items.forEach(item=>node.append(renderer(item)));}
 function accessCard(item){const card=document.createElement('article');card.className='panel';const title=document.createElement('h3');title.textContent=item.name;const meta=document.createElement('p');meta.textContent=`${item.city} · ${date(item.starts_at)} · ${item.status}`;const permissions=document.createElement('small');permissions.textContent=[item.can_edit&&'Edit',item.can_scan&&'Scan',item.can_export&&'Export',item.can_manage_members&&'Manage volunteers'].filter(Boolean).join(' · ')||'View only';card.append(title,meta,permissions);return card;}
 function renderAccount(data){account=data;referralLink=data.referral_link;const creators=data.memberships.filter(m=>m.membership_type==='creator'),volunteers=data.memberships.filter(m=>m.membership_type==='volunteer');$('#greeting').textContent=`Good to see you, ${data.user.name.split(/\s+/)[0]}.`;$('#identity').textContent=data.user.email+(data.user.phone?` · ${data.user.phone}`:'');$('#ticket-count').textContent=data.tickets.filter(t=>t.status==='active').length;$('#wallet-amount').textContent=money(data.wallet.available_paise);$('#team-count').textContent=data.memberships.length;$('#referral-code').textContent=data.user.referral_code;$('#ref-available').textContent=money(data.wallet.available_paise);$('#ref-pending').textContent=money(data.wallet.pending_paise);$('#ref-threshold').textContent=money(data.payout_threshold_paise);$('#request-payout').disabled=data.wallet.available_paise<data.payout_threshold_paise;
  rows($('#order-list'),data.orders,o=>{const row=document.createElement('article');row.className='list-row';const a=document.createElement('div'),b=document.createElement('div');const strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=o.event_name;small.textContent=`${o.reference} · ${date(o.created_at)}`;a.append(strong,small);b.textContent=`${money(o.amount_paise)} · ${o.status}`;row.append(a,b);return row;},'No registrations yet. Your reservations and paid orders will appear here.');
  rows($('#ticket-list'),data.tickets,t=>{const card=document.createElement('article');card.className='panel';const h=document.createElement('h3'),p=document.createElement('p'),s=document.createElement('small');h.textContent=t.event_name;p.textContent=t.pass_name;s.textContent=t.status==='active'?'QR available for entry':`Ticket ${t.status}`;card.append(h,p,s);return card;},'No tickets yet. Tickets are issued only after payment is verified.');
  rows($('#creator-events'),creators,accessCard,'Creator access appears here when a superadmin adds you to an event.');rows($('#volunteer-events'),volunteers,accessCard,'Volunteer assignments appear here when a superadmin adds you to an event.');
  $('#creator-tab').hidden=!creators.length;$('#volunteer-tab').hidden=!volunteers.length;const canEdit=creators.some(m=>m.can_edit);$('#admin-tab').hidden=data.user.role!=='admin'&&!canEdit;$('#admin-tab').textContent=data.user.role==='admin'?'Superadmin':'Event editor';$('#new').hidden=data.user.role!=='admin';
 }
 function enhanceTickets(data){[...$('#ticket-list').children].forEach((card,index)=>{const ticket=data.tickets[index];if(!ticket||ticket.status!=='active')return;const image=document.createElement('img');image.src=`/api/account/tickets/${ticket.id}/qr`;image.alt=`Entry QR for ${ticket.event_name}`;image.style.cssText='display:block;width:min(260px,100%);aspect-ratio:1;margin:18px auto 0;border-radius:16px;background:#fff;padding:10px';card.append(image);});}
 function enhanceVolunteerTools(data){const volunteering=data.memberships.filter(item=>item.membership_type==='volunteer');[...$('#volunteer-events').children].forEach((card,index)=>{const assignment=volunteering[index];if(!assignment?.can_scan)return;const form=document.createElement('form');form.className='scanner';form.innerHTML='<div class="scanner-actions"><button type="button" class="primary" data-camera>Scan QR with camera</button><button type="button" class="quiet" data-stop hidden>Stop camera</button></div><video playsinline muted hidden></video><label>Or paste the ticket token<input name="token" required minlength="32" placeholder="Ticket token"></label><button class="quiet" type="submit">Validate token</button><p role="status" aria-live="polite"></p>';const status=form.querySelector('[role=status]'),video=form.querySelector('video'),camera=form.querySelector('[data-camera]'),stop=form.querySelector('[data-stop]');let stream=null,scanning=false;const redeem=async token=>{try{const result=await api('/api/scan/redeem',{method:'POST',body:JSON.stringify({event_id:assignment.event_id,token})});status.textContent=result.ticket.result==='valid'?'Valid ticket — entry recorded.':result.ticket.result==='used'?'Already used.':'Invalid ticket.';if(result.ticket.result==='valid')navigator.vibrate?.(80);}catch(error){status.textContent=error.message;}};const stopCamera=()=>{scanning=false;stream?.getTracks().forEach(track=>track.stop());stream=null;video.srcObject=null;video.hidden=true;stop.hidden=true;camera.hidden=false;};stop.onclick=stopCamera;camera.onclick=async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){status.textContent='Camera QR scanning is unavailable in this browser. Paste the ticket token below.';return;}try{const detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=stream;video.hidden=false;stop.hidden=false;camera.hidden=true;scanning=true;await video.play();const read=async()=>{if(!scanning)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){const token=codes[0].rawValue;form.elements.token.value=token;stopCamera();await redeem(token);return;}}catch{}requestAnimationFrame(read);};requestAnimationFrame(read);}catch{stopCamera();status.textContent='Camera access could not start. Check permission or paste the ticket token below.';}};form.onsubmit=async event=>{event.preventDefault();await redeem(new FormData(form).get('token'));};card.append(form);});}
 async function loadCoupons(){couponPanel.hidden=false;const [{events},{coupons}]=await Promise.all([api('/api/admin/events'),api('/api/admin/coupons')]),select=$('#coupon-form').elements.event_id,selected=select.value;select.replaceChildren(new Option('All events',''));for(const event of events)select.append(new Option(`${event.name} · ${event.city}`,event.id));select.value=selected;rows($('#coupon-list'),coupons,coupon=>{const row=document.createElement('article'),info=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('small'),deactivate=document.createElement('button');row.className='list-row';title.textContent=coupon.code;const discount=coupon.discount_type==='percent'?`${coupon.value/100}% off`:`${money(coupon.value)} off`;detail.textContent=`${discount} · ${coupon.event_name||'All events'}${coupon.expires_at?` · ends ${date(coupon.expires_at)}`:''}`;info.append(title,detail);deactivate.type='button';deactivate.className='quiet';deactivate.textContent=coupon.active?'Deactivate':'Inactive';deactivate.disabled=!coupon.active;deactivate.onclick=async()=>{try{await api(`/api/admin/coupons/${coupon.id}`,{method:'DELETE'});await loadCoupons();message(`${coupon.code} was deactivated.`);}catch(error){message(error.message);}};row.append(info,deactivate);return row;},'No coupons yet. Create one for all events or a single event.');}
 async function enter(){const data=await api('/api/account'),params=new URLSearchParams(location.search),returnTo=params.get('return');if(returnTo&&returnTo.startsWith('/')&&!returnTo.startsWith('//')){location.href=returnTo;return;}$('#auth').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;renderAccount(data);enhanceTickets(data);enhanceVolunteerTools(data);const requested=params.get('view');if(['overview','tickets','referrals','creator','volunteer','superadmin'].includes(requested))switchView(requested);if(data.user.role==='admin'){await list();await loadCoupons();}else if(data.memberships.some(m=>m.can_edit))await list();}
 async function submitAuth(form,path){const button=form.querySelector('button[type=submit],button:not([type])');button.disabled=true;try{await api(path,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await enter();}catch(e){message(e.message);}finally{button.disabled=false;}}
 $('#login').onsubmit=e=>{e.preventDefault();submitAuth(e.currentTarget,'/api/auth/login');};$('#signup').onsubmit=e=>{e.preventDefault();submitAuth(e.currentTarget,'/api/auth/signup');};
 $('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});location.reload();}catch(e){message(e.message);}};
 $('#copy-referral').onclick=async()=>{try{await navigator.clipboard.writeText(referralLink);message('Referral link copied.');}catch{message(referralLink);}};
 $('#request-payout').onclick=async()=>{try{const {payout}=await api('/api/account/payouts',{method:'POST'});message(`Redemption request ${payout.id.slice(0,8)} was created.`);await enter();switchView('referrals');}catch(e){message(e.message);}};
 function passRow(pass={name:'',amount_paise:0,capacity:100,active:true}){const row=document.createElement('div');row.className='pass';if(pass.id)row.dataset.id=pass.id;row.innerHTML='<div class="pass-fields"><label>Pass name<input data-field="name" required maxlength="80"></label><label>Price (₹)<input data-field="amount" type="number" min="0" max="1000000" step="0.01" required></label><label>Capacity<input data-field="capacity" type="number" min="1" max="1000000" step="1" required></label></div><label><input data-field="active" type="checkbox"> Available for sale</label>';row.querySelector('[data-field=name]').value=pass.name;row.querySelector('[data-field=amount]').value=(pass.amount_paise/100).toFixed(2);row.querySelector('[data-field=capacity]').value=pass.capacity;row.querySelector('[data-field=active]').checked=pass.active;$('#passes').append(row);}
 async function list(){const {events}=await api('/api/admin/events');rows($('#event-list'),events,e=>{const b=document.createElement('button');b.className='event-item';const a=document.createElement('span'),s=document.createElement('small');a.textContent=e.name;s.textContent=`${e.city} · ${e.status}`;b.append(a,s);b.onclick=async()=>{try{await edit((await api('/api/admin/events/'+e.id)).event);message('');}catch(err){message(err.message);}};return b;},'No assigned events yet.');}
 async function edit(event){eventId=event?.id||null;version=event?.version;$('#editor').reset();$('#passes').replaceChildren();$('#editor').hidden=false;$('#editor-title').textContent=event?'Edit event':'Create an event';for(const key of ['name','slug','city','venue','description','refund_policy','timezone','status','image_url','maps_url'])if(event)$('#editor').elements[key].value=event[key];for(const key of ['starts_at','ends_at'])if(event)$('#editor').elements[key].value=new Date(event[key]).toISOString().slice(0,16);$('#editor').elements.referral_reward.value=((event?.referral_reward_paise||0)/100).toFixed(0);(event?.passes||[{name:'Standard',amount_paise:0,capacity:100,active:true}]).forEach(passRow);showImage(event?.image_url||'');deleteButton.hidden=!event||account.user.role!=='admin';$('#view').hidden=!event||event.status!=='published';if(event)$('#view').href='/events/'+encodeURIComponent(event.slug)+'/';const canManage=!!event&&(account.user.role==='admin'||account.memberships.some(m=>m.event_id===event.id&&m.membership_type==='creator'&&m.can_manage_members));$('#members').hidden=!canManage;if(canManage){$('#members h3').textContent=account.user.role==='admin'?'Creators and volunteers':'Volunteers for this event';await loadMembers();}}
 $('#new').onclick=()=>{edit(null);switchView('superadmin');};$('#add-pass').onclick=()=>passRow();
 $('#editor').onsubmit=async e=>{e.preventDefault();const b=$('#save');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.currentTarget));for(const key of ['starts_at','ends_at'])data[key]=new Date(data[key]+':00Z').toISOString();data.referral_reward_paise=Math.round(Number(data.referral_reward)*100);delete data.referral_reward;data.passes=[...document.querySelectorAll('.pass')].map(row=>({...(row.dataset.id?{id:row.dataset.id}:{}),name:row.querySelector('[data-field=name]').value,amount_paise:Math.round(Number(row.querySelector('[data-field=amount]').value)*100),capacity:Number(row.querySelector('[data-field=capacity]').value),active:row.querySelector('[data-field=active]').checked}));if(eventId)data.version=version;const result=await api('/api/admin/events'+(eventId?'/'+eventId:''),{method:eventId?'PUT':'POST',body:JSON.stringify(data)});await edit(result.event);await list();message(result.event.status==='published'?'Event saved and published.':'Event saved privately.');}catch(err){message(err.message);}finally{b.disabled=false;}};
 async function loadMembers(){
  const {members}=await api(`/api/admin/events/${eventId}/members`),platformAdmin=account.user.role==='admin';
  rows($('#member-list'),members,m=>{const row=document.createElement('article'),info=document.createElement('div'),name=document.createElement('strong'),email=document.createElement('small'),actions=document.createElement('div');row.className='member-row';name.textContent=m.name;email.textContent=`${m.email} · ${m.membership_type}`;info.append(name,email);
   if(platformAdmin){const controls=document.createElement('div'),save=document.createElement('button');controls.className='permissions';for(const [key,label] of Object.entries({can_edit:'Edit',can_scan:'Scan',can_export:'Export',can_manage_members:'Manage team'})){const wrap=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=m[key];input.dataset.permission=key;input.disabled=key==='can_manage_members'&&m.membership_type==='creator';wrap.className='chip';wrap.append(input,document.createTextNode(' '+label));controls.append(wrap);}save.type='button';save.className='quiet';save.textContent='Save access';save.onclick=async()=>{const payload={user_id:m.user_id,membership_type:m.membership_type};controls.querySelectorAll('[data-permission]').forEach(input=>payload[input.dataset.permission]=input.checked);try{await api(`/api/admin/events/${eventId}/members`,{method:'PUT',body:JSON.stringify(payload)});await loadMembers();message('Permissions updated.');}catch(err){message(err.message);}};row.append(info,controls);actions.append(save);}else row.append(info);
   if(platformAdmin||m.membership_type==='volunteer'){const remove=document.createElement('button');remove.type='button';remove.className='quiet';remove.textContent='Remove';remove.onclick=async()=>{try{await api(`/api/admin/events/${eventId}/members/${m.user_id}`,{method:'DELETE'});await loadMembers();message('Event access removed.');}catch(err){message(err.message);}};actions.append(remove);}if(actions.children.length)row.append(actions);return row;},'No volunteers assigned yet.');
 }
 let searchTimer;$('#user-search').oninput=e=>{clearTimeout(searchTimer);const query=e.target.value.trim();if(query.length<2)return $('#user-results').replaceChildren();searchTimer=setTimeout(async()=>{try{const {users}=await api('/api/admin/users?query='+encodeURIComponent(query)+'&event_id='+encodeURIComponent(eventId));rows($('#user-results'),users,u=>{const row=document.createElement('article'),info=document.createElement('div'),name=document.createElement('strong'),email=document.createElement('small'),actions=document.createElement('div');row.className='user-result';name.textContent=u.name;email.textContent=u.email;info.append(name,email);const roles=account.user.role==='admin'?['creator','volunteer']:['volunteer'];for(const role of roles){const b=document.createElement('button');b.type='button';b.className='quiet';b.textContent=`Add ${role}`;b.onclick=()=>assign(u.id,role);actions.append(b);}row.append(info,actions);return row;},'No registered users found.');}catch(err){message(err.message);}},250);};
 async function assign(userId,role){try{await api(`/api/admin/events/${eventId}/members`,{method:'PUT',body:JSON.stringify({user_id:userId,membership_type:role,can_edit:role==='creator',can_scan:role==='volunteer',can_export:role==='creator',can_manage_members:role==='creator'})});$('#user-search').value='';$('#user-results').replaceChildren();await loadMembers();message(`${role[0].toUpperCase()+role.slice(1)} access assigned.`);}catch(err){message(err.message);}}
 const memberObserver=new MutationObserver(()=>{$('#member-list').querySelectorAll('.permissions').forEach(node=>node.style.cssText='display:flex;gap:8px;flex-wrap:wrap');$('#member-list').querySelectorAll('.chip').forEach(node=>node.style.margin='0');$('#member-list').querySelectorAll('.chip input').forEach(node=>node.style.cssText='display:inline;width:auto;margin:0');});memberObserver.observe($('#member-list'),{childList:true,subtree:true});
 $('#editor').elements.image_url.addEventListener('input',e=>showImage(e.target.value.trim()));
 $('#image-upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){message('Choose an image smaller than 8 MB.');e.target.value='';return;}message('Uploading image…');e.target.disabled=true;try{const response=await fetch('/api/admin/uploads/event-image',{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await response.json();if(!response.ok)throw Error(data.error||'Upload failed');$('#editor').elements.image_url.value=data.url;showImage(data.url);message('Image uploaded and ready to save with the event.');}catch(err){message(err.message);}finally{e.target.disabled=false;e.target.value='';}});
 deleteButton.onclick=()=>{if(!eventId)return;$('#delete-copy').textContent=`“${$('#editor').elements.name.value}” will be permanently deleted.`;deleteDialog.showModal();};deleteDialog.querySelector('[data-cancel]').onclick=()=>deleteDialog.close();deleteDialog.querySelector('[data-confirm]').onclick=async e=>{e.target.disabled=true;try{await api('/api/admin/events/'+eventId,{method:'DELETE'});deleteDialog.close();eventId=null;$('#editor').hidden=true;await list();message('Event permanently deleted.');}catch(err){deleteDialog.close();message(err.message);}finally{e.target.disabled=false;}};
 $('#coupon-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type=submit],button:not([type])'),data=Object.fromEntries(new FormData(form));button.disabled=true;try{const payload={code:data.code.trim().toUpperCase(),event_id:data.event_id||null,discount_type:data.discount_type,value:Math.round(Number(data.value)*100),min_spend_paise:Math.round(Number(data.min_spend||0)*100),max_uses:data.max_uses?Number(data.max_uses):null,per_customer:Number(data.per_customer),expires_at:data.expires_at?new Date(data.expires_at).toISOString():null,active:true};await api('/api/admin/coupons',{method:'POST',body:JSON.stringify(payload)});form.reset();form.elements.min_spend.value='0';form.elements.per_customer.value='1';await loadCoupons();message(`${payload.code} is ready to use.`);}catch(error){message(error.message);}finally{button.disabled=false;}};
 api('/api/auth/me').then(enter).catch(()=>{});
})();
